{"function":"() => {
const res=[];
function walk(node, host){
  for(const el of node.querySelectorAll('*')){
    const ti = el.tabIndex;
    const focusable = ti>=0 && !el.disabled && el.getClientRects().length>0 && getComputedStyle(el).visibility!=='hidden';
    if(focusable && (el.matches('a[href],button,input,select,textarea,iframe,[tabindex],summary,[contenteditable]'))) res.push((host?host+' >> ':'')+el.tagName.toLowerCase()+(el.id?'#'+el.id:'')+'['+(el.getAttribute('aria-label')||el.textContent.trim().slice(0,30))+'] ti='+el.getAttribute('tabindex'));
    if(el.shadowRoot) walk(el.shadowRoot, (host?host+'>':'')+el.tagName.toLowerCase()+(el.id?'#'+el.id:''));
  }
}
walk(document,'');
const a=[...document.querySelectorAll('pnip-mpa-processos a[role=button]')].map(a=>({ti:a.tabIndex, href:a.getAttribute('href'), color:getComputedStyle(a).color}));
const tags=[...document.querySelectorAll('pnip-mpa-processos span.br-tag')].map(s=>({ti:s.tabIndex, role:s.getAttribute('role')}));
return {res, a:a.slice(0,2), tags};
}"}

