{"function":"async () => {
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const results=[];
for (const idx of [1,2,3,5,7,8]) {
  // ensure on list
  if(!location.pathname.endsWith('/processos')){ history.back(); await sleep(1500); }
  const rows=[...document.querySelectorAll('pnip-mpa-processos tbody tr')];
  const r=rows[idx]; if(!r){results.push({idx,err:'no row'});continue;}
  const status=r.querySelectorAll('td')[7].textContent.trim(); const tipo=r.querySelectorAll('td')[3].textContent.trim();
  const btn=r.querySelector('br-button[title="Ver processo"]'); (btn.shadowRoot.querySelector('button')||btn).click();
  await sleep(1500);
  const main=document.querySelector('main');
  const icons=[...main.querySelectorAll('br-icon-base[style*=cursor]')].length;
  results.push({idx,status,tipo,url:location.pathname, h:[...document.querySelectorAll('h1,h2,h3,h4,h5,h6')].map(e=>e.tagName+':'+e.textContent.trim().slice(0,40)), text:main.innerText.replace(/\s+/g,' ').slice(0,400), icons, comps:[...main.querySelectorAll('*')].filter(e=>e.tagName.startsWith('PNIP-')).map(e=>e.tagName).filter((v,i,a)=>a.indexOf(v)===i).join(',')});
}
if(!location.pathname.endsWith('/processos')){ history.back(); await sleep(1500); }
return results;
}"}

